static const z_t58_t _zag1685[] = {{ .data = "@chan", .size = 5 }, { .data = "@cond_init", .size = 10 }, { .data = "@mutex_init", .size = 11 }, { .data = "@panic", .size = 6 }, { .data = "@xmalloc", .size = 8 }};

static const z_t6128_t _zag1686 = { { .data = "chan_new", .size = 8 }, { .length = 1, .data = _zag1684 }, { .length = 5, .data = _zag1685 }, { .data = "static z_chan* z_chan_new(size_t elemSize, void (*destroyElem)(void*), uint64_t capacity) {\n    z_chan* b = (z_chan*)z_xmalloc(sizeof(z_chan));\n    if (z_mutex_init(&b->m) != 0 || z_cond_init(&b->notEmpty) != 0 || z_cond_init(&b->notFull) != 0) {\n        z_panic(\"sync.Receiver: the operating system could not make a lock\");\n    }\n    b->elemSize = elemSize;\n    b->destroyElem = destroyElem;\n    b->cap = capacity;\n    b->size = capacity != 0 ? capacity : 16;\n    b->ring = (unsigned char*)z_xmalloc(elemSize * b->size);\n    b->head = 0;\n    b->len = 0;\n    b->senders = 0;\n    b->receiverAlive = true;\n    return b;\n}", .size = 619 } };
